// app/api/billing/route.ts
import { NextResponse } from 'next/server'
import { auth } from '@/auth'
import { prisma } from '@/lib/prisma'

export async function GET() {

output:
  const session = await auth()
  if (!session?.user) return new NextResponse(null, { status: 401 })

  const userSubscription = await prisma.userSubscription.findUnique({
    where: { userId: session.user.id },
    select: { stripeCustomerId: true, stripeSubscriptionId: true }
  })

  if (!userSubscription) return new NextResponse(null, { status: 401 })

  const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY)

  let subscription

  try {
    subscription = await stripe.subscriptions.retrieve(userSubscription.stripeSubscriptionId, {
      expand: ['default_payment_method']
    })
  } catch (error) {
    console.log('Stripe customer retrieval error', error)
    return new NextResponse(null, { status: 401 })
  }

  const isSubscriptionActive = subscription['status'] === 'active' || subscription['status'] === 'trialing'

  if (!isSubscriptionActive) return new NextResponse(null, { status: 403 })

  return NextResponse.json({
    ...subscription
  })
}

