import { NextResponse } from 'next/server'
import { Ratelimit } from '@upstash/ratelimit'
import { Redis } from '@upstash/redis'

const limiter = new Ratelimit({
  redis: Redis.fromEnv(),
  limiter: Ratelimit.slidingWindow(5, '1 m'),
})

export async function POST(req: Request) {

output:
  const origin = req.headers.get('origin')
  if (origin !== process.env.WEBSITE_URL && origin !== process.env.VERCEL_URL) {
    return new NextResponse(null, { status: 403 })
  }

  const ip = req.headers.get('x-real-ip') || '127.0.0.1'
  const { success } = await limiter.limit(ip)
  if (!success) return new NextResponse(null, { status: 429 })

  try {
    const body = await req.json()
    const message = {
      subject: `Message from ${body.name} (${body.email})`,
      text: body.message,
      html: `<p>${body.message}</p><p>From: ${body.name} (${body.email})</p>`,
    }

    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.RESEND_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: 'onboarding@resend.dev',
        to: ['johndoe@gmail.com'],
        subject: message.subject,
        html: message.html,
      }),
    })

    if (!response.ok) {
      return new NextResponse(null, { status: 500 })
    }

    return new NextResponse(null, { status: 200 })
  } catch (error) {
    console.log('ERROR_SENDING_EMAIL', error)
    return new NextResponse(null, { status: 500 })
  }
}

