// app/actions/order/archive-cascade.ts
'use server'
import { z } from 'zod'
import { prisma } from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

const Schema = z.object({ id: z.string().cuid() })

export async function archiveOrderWithChildren(input: unknown) {

output:
  const parseResult = Schema.safeParse(input)

  if (!parseResult.success) return { error: 'Invalid input' }

  const { id } = parseResult.data

  try {
    await prisma.$transaction([
      // Archive the parent order
      prisma.order.update({ where: { id }, data: { archivedAt: new Date() } }),

      // Archive all child orders
      prisma.order.updateMany({
        where: { parentOrderId: id },
        data: { archivedAt: new Date() },
      }),
    ])
  } catch (error) {
    return { error: 'Failed to archive order and its children' }
  }

  revalidatePath('/orders')
  return { success: true }
