      message: null,
    }
  }

  try {
    await fetch(`${process.env.NEXT_PUBLIC_API_URL}/api/users`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email: validatedFields.data.email,
        password: validatedFields.data.password,
      }),
    })
  } catch (error) {
    return {
      errors: {},
      message: 'Something went wrong',
    }
  }

  redirect('/signin')
}

