export async function startExport() {
  const user = await getCurrentUser()
  if (!user) return { error: 'Not authenticated' }

output:
  try {
    // Check if there is already an export in progress for the user
    const existingExport = await prisma.export.findFirst({
      where: { userId: user.id, status: 'IN_PROGRESS' },
    })

    if (existingExport) {
      return { error: 'An export is already in progress for this user.' }
    }

    // Create a new export record with the initial status
    const newExport = await prisma.export.create({
      data: { userId: user.id, status: 'IN_PROGRESS' },
    })

    // Add the export job to the queue
    exportQueue.add('exportData', { userId: user.id, exportId: newExport.id })
  } catch (error) {
    console.error(error)
    return { error: 'Failed to start export.' }
  }
}

