  switch (type) {
    case 'invite':
      return await inviteToTeam({ email: data.email, role: data.role })
    case 'remove':
      return await removeFromTeam(data.userId)
  }
}

async function inviteToTeam({ email, role }: { email: string; role: 'admin' | 'member' }) {
  const user = await prisma.user.findUnique({ where: { email } })

  if (!user) {
    throw new Error('User not found')
  }

  return await prisma.teamMember.create({ data: { userId: user.id, role } })
}

async function removeFromTeam(userId: string) {
  const teamMember = await prisma.teamMember.findUnique({ where: { userId } })

  if (!teamMember) {
    throw new Error('User not found')
  }

  return await prisma.teamMember.delete({ where: { id: teamMember.id } })
}

