'use server'
import { cookies } from 'next/headers'
import { prisma } from '@/lib/db'

const SESSION_EXTEND_DAYS = 30

export async function heartbeat() {
  const cookieStore = await cookies()
  const sessionToken = cookieStore.get('session')?.value
  if (!sessionToken) return { ok: false }

output:
  try {
    const session = await prisma.session.findUnique({ where: { token: sessionToken } })
    if (!session) return { ok: false }

    // Extend the session expiry date
    await prisma.session.update({
      where: { id: session.id },
      data: { expiresAt: new Date(Date.now() + SESSION_EXTEND_DAYS * 24 * 60 * 60 * 1000) }
    })

    return { ok: true }
  } catch (error) {
    console.error('Error extending session:', error)
    return { ok: false }
  }
}

