// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private listeners: Partial<Record<keyof E, Array<(payload: E[keyof E]) => void>>> = {}

  on<K extends keyof E>(eventName: K, listener: (payload: E[K]) => void) {
    if (!this.listeners[eventName]) this.listeners[eventName] = []
    this.listeners[eventName]?.push(listener)
  }

  off<K extends keyof E>(eventName: K, listenerToRemove: (payload: E[K]) => void) {
    const filterListeners = (listener: (payload: E[K]) => void) => listener !== listenerToRemove
    this.listeners[eventName] = this.listeners[eventName]?.filter(filterListeners)
  }

  emit<K extends keyof E>(eventName: K, payload: E[K]) {
    this.listeners[eventName]?.forEach((listener) => listener(payload))
  }
}

