/**
 * Returns a function, that, when invoked, only calls the original function at most once per every given wait milliseconds.
 * @param {Function} func - Function to wrap
 * @param {Number} wait - Number of milliseconds to delay invocation
 * @returns {Function} Wrapped function
 */
export const throttle = (func, wait) => {
  let context;
  let args;
  let result;
  let timeout = null;
  let previous = 0;

  const later = () => {
    previous = Date.now();
    timeout = null;
    func.apply(context, args);
  };

  return function() {
    const now = Date.now();
    const remaining = wait - (now - previous);

    context = this;
    args = arguments;

    if (remaining <= 0 || remaining > wait) {
      if (timeout) {
        clearTimeout(timeout);
        timeout = null;
      }

      previous = now;
      result = func.apply(context, args);

      if (!timeout) {
        context = args = null;
      }
    } else if (!timeout) {
      timeout = setTimeout(later, remaining);
    }

    return result;
  };
};

