/**
 * Retry an async function with exponential backoff up to maxAttempts
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 500
): Promise<T> {

output:
  let attempt = 1;
  while (true) {
    try {
      return await fn();
    } catch (err) {
      if (attempt >= maxAttempts) throw err;
      const delayMs = baseDelayMs * Math.pow(2, attempt);
      console.log(`Error: ${err}. Retrying in ${delayMs}ms...`);
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    } finally {
      attempt++;
    }
  }
}

